CANON = {"must": ["archive", "search"], "filter": {"year": 2021}, "limit": 10}
def to_sql(q):
    terms = " AND ".join("body LIKE '%%%s%%'" % t for t in q["must"])
    return "SELECT * FROM recs WHERE %s AND year=%d LIMIT %d" % (
        terms, q["filter"]["year"], q["limit"])
def to_rest(q):
    return {"q": " ".join(q["must"]), "year": q["filter"]["year"], "n": q["limit"]}
print("SQL :", to_sql(CANON))
print("REST:", to_rest(CANON))

